export interface Country {
  id: string;
  name: string;
  flag: string;
  ministryUrl: string;
}

export interface Grade {
  id: string;
  name: string;
}

export interface Stream {
  id: string;
  name: string;
}

export interface Subject {
  id: string;
  name: string;
  icon: string;
}

export interface Lesson {
  title: string;
  summary: string;
  content: string;
  sources: string[];
}

export interface Exam {
  id: string;
  title: string;
  year: string;
  term: string;
  url: string;
}

export enum AppStep {
  COUNTRY_SELECTION,
  GRADE_SELECTION,
  STREAM_SELECTION,
  SUBJECT_SELECTION,
  ACTION_CHOICE,
  LESSON_LIST,
  LESSON_VIEW,
  EXAM_LIST
}

export interface AppState {
  country?: Country;
  grade?: Grade;
  stream?: Stream;
  subject?: Subject;
  mode?: 'lessons' | 'exams';
  currentStep: AppStep;
}

import { GoogleGenAI, Type } from "@google/genai";
import { Country, Grade, Stream, Subject, Lesson, Exam } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const fetchLessonList = async (country: Country, grade: Grade, stream: Stream, subject: Subject): Promise<string[]> => {
  try {
    const prompt = `List the names of main lessons for the subject ${subject.name} in ${country.name} for ${grade.name} (${stream.name} stream), according to the official Ministry of Education curriculum. Provide only the list of titles.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text.trim());
    }
    return ["درس تمهيدي", "مقدمة في المادة"];
  } catch (error) {
    console.error("Error fetching lessons:", error);
    return ["تعذر جلب الدروس، يرجى المحاولة لاحقاً"];
  }
};

export const generateLessonContent = async (country: Country, grade: Grade, stream: Stream, subject: Subject, lessonTitle: string): Promise<Lesson> => {
  const prompt = `
    Provide a simplified and clear explanation for the lesson "${lessonTitle}" for ${grade.name} students in ${country.name} (${stream.name} stream).
    The explanation must:
    1. Be aligned with the official Ministry of Education curriculum of ${country.name}.
    2. Use clear Arabic language (Fusha).
    3. Include examples and clear headings.
    4. Provide a summary at the end.
    5. List at least 2 official URLs or sources from ${country.name} (like ${country.ministryUrl}) where the student can find more info.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            summary: { type: Type.STRING },
            content: { type: Type.STRING, description: "Detailed explanation with markdown headings" },
            sources: { type: Type.ARRAY, items: { type: Type.STRING } }
          },
          required: ["title", "summary", "content", "sources"]
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text.trim());
    }
    throw new Error("No response text");
  } catch (error) {
    return {
      title: lessonTitle,
      summary: "عذراً، حدث خطأ أثناء جلب محتوى الدرس.",
      content: "يرجى التحقق من اتصالك بالإنترنت والمحاولة مرة أخرى.",
      sources: []
    };
  }
};

export const fetchExams = async (country: Country, grade: Grade, stream: Stream, subject: Subject, term: string): Promise<Exam[]> => {
  const prompt = `
    Find official past exams for ${subject.name} in ${country.name} for ${grade.name} (${stream.name} stream) for ${term}.
    Only provide exams from official ministry of education portals or trusted national educational platforms.
    Return a list of up to 10 entries with titles, years, and direct links if possible.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              title: { type: Type.STRING },
              year: { type: Type.STRING },
              term: { type: Type.STRING },
              url: { type: Type.STRING }
            },
            required: ["id", "title", "year", "term", "url"]
          }
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text.trim());
    }
    return [];
  } catch (error) {
    console.error("Error fetching exams:", error);
    return [];
  }
};

