import React, { useState, useEffect } from 'react';
import { 
  AppStep, 
  AppState, 
  Country, 
  Grade, 
  Stream, 
  Subject, 
  Lesson, 
  Exam 
} from './types';
import { 
  COUNTRIES, 
  STREAMS, 
  SUBJECTS 
} from './constants';
import Layout from './components/Layout';
import * as gemini from './services/geminiService';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    currentStep: AppStep.COUNTRY_SELECTION
  });
  const [loading, setLoading] = useState(false);
  const [dynamicGrades, setDynamicGrades] = useState<Grade[]>([]);
  const [lessonList, setLessonList] = useState<string[]>([]);
  const [currentLesson, setCurrentLesson] = useState<Lesson | null>(null);
  const [exams, setExams] = useState<Exam[]>([]);
  const [term, setTerm] = useState('الفصل الأول');

  const handleCountrySelect = async (country: Country) => {
    setLoading(true);
    setState(prev => ({ ...prev, country }));
    const grades = await gemini.fetchGrades(country);
    setDynamicGrades(grades);
    setState(prev => ({ ...prev, currentStep: AppStep.GRADE_SELECTION }));
    setLoading(false);
  };

  const handleGradeSelect = (grade: Grade) => {
    setState(prev => ({ ...prev, grade, currentStep: AppStep.STREAM_SELECTION }));
  };

  const handleStreamSelect = (stream: Stream) => {
    setState(prev => ({ ...prev, stream, currentStep: AppStep.SUBJECT_SELECTION }));
  };

  const handleSubjectSelect = (subject: Subject) => {
    setState(prev => ({ ...prev, subject, currentStep: AppStep.ACTION_CHOICE }));
  };

  const handleActionSelect = async (mode: 'lessons' | 'exams') => {
    setState(prev => ({ ...prev, mode }));
    if (mode === 'lessons') {
      setLoading(true);
      const list = await gemini.fetchLessonList(state.country!, state.grade!, state.stream!, state.subject!);
      setLessonList(list);
      setState(prev => ({ ...prev, currentStep: AppStep.LESSON_LIST }));
      setLoading(false);
    } else {
      setState(prev => ({ ...prev, currentStep: AppStep.EXAM_LIST }));
      fetchExams('الفصل الأول');
    }
  };

  const handleLessonSelect = async (lessonTitle: string) => {
    setLoading(true);
    const content = await gemini.generateLessonContent(state.country!, state.grade!, state.stream!, state.subject!, lessonTitle);
    setCurrentLesson(content);
    setState(prev => ({ ...prev, currentStep: AppStep.LESSON_VIEW }));
    setLoading(false);
  };

  const fetchExams = async (selectedTerm: string) => {
    setTerm(selectedTerm);
    setLoading(true);
    const result = await gemini.fetchExams(state.country!, state.grade!, state.stream!, state.subject!, selectedTerm);
    setExams(result);
    setLoading(false);
  };

  const goBack = () => {
    const prevStepMap: Record<AppStep, AppStep> = {
      [AppStep.COUNTRY_SELECTION]: AppStep.COUNTRY_SELECTION,
      [AppStep.GRADE_SELECTION]: AppStep.COUNTRY_SELECTION,
      [AppStep.STREAM_SELECTION]: AppStep.GRADE_SELECTION,
      [AppStep.SUBJECT_SELECTION]: AppStep.STREAM_SELECTION,
      [AppStep.ACTION_CHOICE]: AppStep.SUBJECT_SELECTION,
      [AppStep.LESSON_LIST]: AppStep.ACTION_CHOICE,
      [AppStep.LESSON_VIEW]: AppStep.LESSON_LIST,
      [AppStep.EXAM_LIST]: AppStep.ACTION_CHOICE,
    };
    setState(prev => ({ ...prev, currentStep: prevStepMap[prev.currentStep] }));
  };

  const renderStep = () => {
    if (loading) {
      return (
        <div className="flex flex-col items-center justify-center py-20 space-y-6">
          <div className="w-16 h-16 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-xl font-medium text-slate-600 animate-pulse">جاري جلب البيانات الموثوقة والأنظمة الرسمية...</p>
          <p className="text-sm text-slate-400">نحن نبحث في المناهج والمسميات الرسمية لـ {state.country?.name || 'البلد المختار'}</p>
        </div>
      );
    }

    switch (state.currentStep) {
      case AppStep.COUNTRY_SELECTION:
        return (
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
            {COUNTRIES.map(c => (
              <button 
                key={c.id} 
                onClick={() => handleCountrySelect(c)}
                className="glass p-6 rounded-2xl border border-slate-200 hover:border-blue-500 hover:shadow-xl hover:scale-105 transition-all flex flex-col items-center gap-3 group"
              >
                <span className="text-4xl group-hover:scale-125 transition-transform">{c.flag}</span>
                <span className="font-bold text-slate-700">{c.name}</span>
              </button>
            ))}
          </div>
        );

      case AppStep.GRADE_SELECTION:
        return (
          <div className="space-y-4 max-w-lg mx-auto">
            {dynamicGrades.length > 0 ? (
              dynamicGrades.map(g => (
                <button 
                  key={g.id} 
                  onClick={() => handleGradeSelect(g)}
                  className="w-full text-right p-6 bg-white rounded-2xl border border-slate-200 hover:bg-blue-50 hover:border-blue-300 transition-all flex items-center justify-between group shadow-sm"
                >
                  <span className="text-lg font-bold text-slate-700">{g.name}</span>
                  <span className="text-blue-500 group-hover:translate-x-[-8px] transition-transform">←</span>
                </button>
              ))
            ) : (
              <div className="text-center py-12 bg-white rounded-2xl border-2 border-dashed border-slate-200">
                <p className="text-slate-500">عذراً، لم نتمكن من العثور على البيانات الرسمية للأقسام لهذا البلد حالياً.</p>
                <button onClick={goBack} className="mt-4 text-blue-600 font-bold hover:underline">العودة واختيار بلد آخر</button>
              </div>
            )}
          </div>
        );

      case AppStep.STREAM_SELECTION:
        return (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {STREAMS.map(s => (
              <button 
                key={s.id} 
                onClick={() => handleStreamSelect(s)}
                className="p-8 bg-white rounded-2xl border border-slate-200 hover:border-blue-500 hover:shadow-lg transition-all text-center group"
              >
                <h3 className="text-xl font-bold text-slate-800 mb-2">{s.name}</h3>
                <p className="text-sm text-slate-500">المواد العلمية والأدبية المتخصصة</p>
              </button>
            ))}
          </div>
        );

      case AppStep.SUBJECT_SELECTION:
        return (
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
            {SUBJECTS.map(subj => (
              <button 
                key={subj.id} 
                onClick={() => handleSubjectSelect(subj)}
                className="p-6 bg-white rounded-2xl border border-slate-200 hover:border-blue-500 hover:shadow-md transition-all flex items-center gap-4 text-right"
              >
                <span className="text-3xl bg-slate-50 p-3 rounded-xl">{subj.icon}</span>
                <span className="font-bold text-slate-700 text-lg">{subj.name}</span>
              </button>
            ))}
          </div>
        );

      case AppStep.ACTION_CHOICE:
        return (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 max-w-2xl mx-auto">
            <button 
              onClick={() => handleActionSelect('lessons')}
              className="p-10 bg-white rounded-3xl border-2 border-slate-100 hover:border-blue-500 hover:shadow-2xl transition-all flex flex-col items-center gap-4 group"
            >
              <div className="w-20 h-20 bg-blue-100 rounded-2xl flex items-center justify-center text-4xl group-hover:rotate-12 transition-transform">📖</div>
              <h3 className="text-2xl font-bold text-slate-800">الدروس والشروحات</h3>
              <p className="text-slate-500 text-center">شروحات مبسطة وملخصات من الكتب المدرسية</p>
            </button>
            <button 
              onClick={() => handleActionSelect('exams')}
              className="p-10 bg-white rounded-3xl border-2 border-slate-100 hover:border-blue-500 hover:shadow-2xl transition-all flex flex-col items-center gap-4 group"
            >
              <div className="w-20 h-20 bg-orange-100 rounded-2xl flex items-center justify-center text-4xl group-hover:rotate-12 transition-transform">📝</div>
              <h3 className="text-2xl font-bold text-slate-800">الامتحانات الرسمية</h3>
              <p className="text-slate-500 text-center">نماذج امتحانات وزارية من السنوات السابقة</p>
            </button>
          </div>
        );

      case AppStep.LESSON_LIST:
        return (
          <div className="space-y-3">
            <p className="text-slate-500 mb-6 bg-blue-50 p-4 rounded-xl border border-blue-100">
              تم جلب قائمة الدروس أدناه بناءً على منهاج وزارة التربية في <strong>{state.country?.name}</strong>.
            </p>
            {lessonList.map((lesson, idx) => (
              <button 
                key={idx} 
                onClick={() => handleLessonSelect(lesson)}
                className="w-full text-right p-5 bg-white rounded-xl border border-slate-200 hover:bg-slate-50 hover:border-blue-400 transition-all flex items-center gap-4"
              >
                <span className="bg-blue-500 text-white w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm">{idx + 1}</span>
                <span className="font-semibold text-slate-700">{lesson}</span>
              </button>
            ))}
          </div>
        );

      case AppStep.LESSON_VIEW:
        return currentLesson && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
            <div className="gradient-bg p-8 text-white">
              <h3 className="text-3xl font-bold mb-3">{currentLesson.title}</h3>
              <p className="text-white/80 leading-relaxed text-lg">{currentLesson.summary}</p>
            </div>
            <div className="p-8 prose prose-slate max-w-none">
              <div className="bg-amber-50 p-6 rounded-2xl border-l-4 border-amber-400 mb-8 italic text-slate-700 leading-8">
                {currentLesson.content.split('\n').map((line, i) => (
                  <p key={i} className="mb-4 last:mb-0">{line}</p>
                ))}
              </div>

              <div className="mt-12 pt-8 border-t border-slate-100">
                <h4 className="font-bold text-slate-800 mb-4 flex items-center gap-2">
                  <span>🔗</span> المصادر الموثوقة:
                </h4>
                <ul className="space-y-3">
                  {currentLesson.sources.map((src, i) => (
                    <li key={i}>
                      <a href={src} target="_blank" rel="noopener noreferrer" className="text-blue-600 hover:underline flex items-center gap-2 overflow-hidden text-ellipsis whitespace-nowrap">
                        <span className="text-xs">🌐</span> {src}
                      </a>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
            <div className="bg-slate-50 p-6 flex justify-between items-center">
               <button onClick={goBack} className="text-slate-600 font-bold">إغلاق الدرس</button>
               <button onClick={() => window.print()} className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold shadow-lg shadow-blue-200">تحميل PDF (طباعة)</button>
            </div>
          </div>
        );

      case AppStep.EXAM_LIST:
        return (
          <div className="space-y-6">
            <div className="flex flex-wrap gap-2 justify-center mb-8">
              {['الفصل الأول', 'الفصل الثاني', 'الفصل الثالث', 'امتحانات نهائية'].map(t => (
                <button 
                  key={t}
                  onClick={() => fetchExams(t)}
                  className={`px-6 py-2 rounded-full font-bold transition-all ${term === t ? 'bg-blue-600 text-white shadow-lg' : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50'}`}
                >
                  {t}
                </button>
              ))}
            </div>

            {exams.length > 0 ? (
              <div className="grid grid-cols-1 gap-4">
                {exams.map(exam => (
                  <div key={exam.id} className="bg-white p-6 rounded-2xl border border-slate-200 flex items-center justify-between shadow-sm hover:shadow-md transition-shadow">
                    <div className="flex flex-col gap-1">
                      <h4 className="font-bold text-lg text-slate-800">{exam.title}</h4>
                      <div className="flex gap-4 text-sm text-slate-500">
                        <span>سنة: {exam.year}</span>
                        <span>الدورة: {exam.term}</span>
                      </div>
                    </div>
                    <a 
                      href={exam.url} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-2 rounded-xl font-bold transition-colors"
                    >
                      تحميل الامتحان
                    </a>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center py-20 bg-white rounded-3xl border-2 border-dashed border-slate-200">
                <span className="text-5xl mb-4 block">📂</span>
                <p className="text-slate-500">لم يتم العثور على امتحانات لهذا الفصل حالياً.</p>
              </div>
            )}
          </div>
        );

      default:
        return null;
    }
  };

  const getStepTitle = () => {
    switch (state.currentStep) {
      case AppStep.COUNTRY_SELECTION: return "اختر بلدك لتخصيص المحتوى";
      case AppStep.GRADE_SELECTION: return `أهلاً بك في ${state.country?.name}، اختر النظام التعليمي المعتمد`;
      case AppStep.STREAM_SELECTION: return "اختر شعبتك الدراسية";
      case AppStep.SUBJECT_SELECTION: return "اختر المادة التعليمية";
      case AppStep.ACTION_CHOICE: return `${state.subject?.name} - ماذا تريد أن تفعل؟`;
      case AppStep.LESSON_LIST: return "قائمة الدروس الرسمية";
      case AppStep.LESSON_VIEW: return "شرح الدرس المبسط";
      case AppStep.EXAM_LIST: return "الامتحانات الوزارية السابقة";
      default: return "";
    }
  };

  return (
    <Layout step={state.currentStep} onBack={goBack} title={getStepTitle()}>
      <div className="animate-in fade-in duration-700">
        {renderStep()}
      </div>
    </Layout>
  );
};

