import { GoogleGenAI, Type } from "@google/genai";
import { Country, Grade, Stream, Subject, Lesson, Exam } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

/**
 * Fetches official grade levels/years for a specific country using Search Grounding.
 */
export const fetchGrades = async (country: Country): Promise<Grade[]> => {
  const prompt = `
    Based only on the official Ministry of Education website (${country.ministryUrl}) and official curriculum documents for ${country.name}, 
    list the official secondary education grade levels/years (e.g., 1st Secondary, 2nd Secondary, Grade 10, etc.).
    Use the EXACT official Arabic terminology used in ${country.name}.
    Return a list of grade objects with id and official name.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              name: { type: Type.STRING }
            },
            required: ["id", "name"]
          }
        }
      }
    });

    return response.text ? JSON.parse(response.text.trim()) : [];
  } catch (error) {
    console.error("Error fetching grades:", error);
    return [];
  }
};

