import Layout from './components/Layout';
import * as gemini from './services/geminiService';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    currentStep: AppStep.COUNTRY_SELECTION
  });
  const [loading, setLoading] = useState(false);
  const [dynamicGrades, setDynamicGrades] = useState<Grade[]>([]);
  const [dynamicStreams, setDynamicStreams] = useState<Stream[]>([]);
  const [dynamicSubjects, setDynamicSubjects] = useState<Subject[]>([]);
  const [lessonList, setLessonList] = useState<string[]>([]);
  const [currentLesson, setCurrentLesson] = useState<Lesson | null>(null);

  // Exam Selection Flow State
  const [exams, setExams] = useState<Exam[]>([]);
  const [selectedTerm, setSelectedTerm] = useState<string | null>(null);
  const [selectedQuantity, setSelectedQuantity] = useState<number | null>(null);
  const [examStep, setExamStep] = useState<'period' | 'quantity' | 'results'>('period');

  const handleCountrySelect = async (country: Country) => {
    setLoading(true);
    setState(prev => ({ ...prev, country }));
    const grades = await gemini.fetchGrades(country);
    setDynamicGrades(grades);
    setState(prev => ({ ...prev, currentStep: AppStep.GRADE_SELECTION }));
    setLoading(false);
  };

  const handleGradeSelect = async (grade: Grade) => {
    setLoading(true);
    setState(prev => ({ ...prev, grade }));
    const streams = await gemini.fetchStreams(state.country!, grade);
    setDynamicStreams(streams);
    setState(prev => ({ ...prev, currentStep: AppStep.STREAM_SELECTION }));
    setLoading(false);
  };

  const handleStreamSelect = async (stream: Stream) => {
    setLoading(true);
    setState(prev => ({ ...prev, stream }));
    const subjects = await gemini.fetchSubjects(state.country!, state.grade!, stream);
    setDynamicSubjects(subjects);
    setState(prev => ({ ...prev, currentStep: AppStep.SUBJECT_SELECTION }));
    setLoading(false);
  };

  const handleSubjectSelect = (subject: Subject) => {
    setState(prev => ({ ...prev, subject, currentStep: AppStep.ACTION_CHOICE }));
  };

  const handleActionSelect = async (mode: 'lessons' | 'exams') => {
    setState(prev => ({ ...prev, mode }));
    if (mode === 'lessons') {
      setLoading(true);
      const list = await gemini.fetchLessonList(state.country!, state.grade!, state.stream!, state.subject!);
      setLessonList(list);
      setState(prev => ({ ...prev, currentStep: AppStep.LESSON_LIST }));
      setLoading(false);
    } else {
      setSelectedTerm(null);
      setSelectedQuantity(null);
      setExamStep('period');
      setState(prev => ({ ...prev, currentStep: AppStep.EXAM_LIST }));
    }
  };

  const handlePeriodSelect = (term: string) => {
    setSelectedTerm(term);
    setExamStep('quantity');
  };

  const handleQuantitySelect = async (qty: number) => {
    setSelectedQuantity(qty);
    setLoading(true);
    const results = await gemini.fetchExams(
      state.country!,
      state.grade!,
      state.stream!,
      state.subject!,
      selectedTerm!,
      qty
    );
    setExams(results);
    setExamStep('results');
    setLoading(false);
  };

  const handleLessonSelect = async (lessonTitle: string) => {
    setLoading(true);
    const content = await gemini.generateLessonContent(state.country!, state.grade!, state.stream!, state.subject!, lessonTitle);
    setCurrentLesson(content);
    setState(prev => ({ ...prev, currentStep: AppStep.LESSON_VIEW }));
    setLoading(false);
  };

  const goBack = () => {
    if (state.currentStep === AppStep.EXAM_LIST) {
      if (examStep === 'quantity') { setExamStep('period'); return; }
      if (examStep === 'results') { setExamStep('quantity'); return; }
    }

    const prevStepMap: Record<AppStep, AppStep> = {
      [AppStep.COUNTRY_SELECTION]: AppStep.COUNTRY_SELECTION,
      [AppStep.GRADE_SELECTION]: AppStep.COUNTRY_SELECTION,
      [AppStep.STREAM_SELECTION]: AppStep.GRADE_SELECTION,
      [AppStep.SUBJECT_SELECTION]: AppStep.STREAM_SELECTION,
      [AppStep.ACTION_CHOICE]: AppStep.SUBJECT_SELECTION,
      [AppStep.LESSON_LIST]: AppStep.ACTION_CHOICE,
      [AppStep.LESSON_VIEW]: AppStep.LESSON_LIST,
      [AppStep.EXAM_LIST]: AppStep.ACTION_CHOICE,
    };
    setState(prev => ({ ...prev, currentStep: prevStepMap[prev.currentStep] }));
  };

  const renderStep = () => {
    if (loading) {
      return (
        <div className="flex flex-col items-center justify-center py-20 space-y-6">
          <div className="w-16 h-16 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-xl font-medium text-slate-600 animate-pulse text-center">جاري جلب البيانات من المصادر الرسمية الموثوقة...</p>
          <p className="text-sm text-slate-400 text-center">نحن نبحث في المواقع الوزارية والكتب المعتمدة لـ {state.country?.name}</p>
        </div>
      );
    }

    switch (state.currentStep) {
      case AppStep.COUNTRY_SELECTION:
        return (
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
            {COUNTRIES.map(c => (
              <button 
                key={c.id} 
                onClick={() => handleCountrySelect(c)}
                className="glass p-6 rounded-2xl border border-slate-200 hover:border-blue-500 hover:shadow-xl hover:scale-105 transition-all flex flex-col items-center gap-3 group"
              >
                <span className="text-4xl group-hover:scale-125 transition-transform">{c.flag}</span>
                <span className="font-bold text-slate-700">{c.name}</span>
              </button>
            ))}
          </div>
        );

      case AppStep.GRADE_SELECTION:
        return (
          <div className="space-y-4 max-w-lg mx-auto">
            {dynamicGrades.length > 0 ? dynamicGrades.map(g => (
              <button key={g.id} onClick={() => handleGradeSelect(g)} className="w-full text-right p-6 bg-white rounded-2xl border border-slate-200 hover:bg-blue-50 hover:border-blue-300 transition-all flex items-center justify-between shadow-sm">
                <span className="text-lg font-bold text-slate-700">{g.name}</span>
                <span className="text-blue-500">←</span>
              </button>
            )) : <div className="text-center py-12">البيانات غير متوفرة حالياً</div>}
          </div>
        );

      case AppStep.STREAM_SELECTION:
        return (
          <div className="space-y-4 max-w-lg mx-auto">
            {dynamicStreams.length > 0 ? dynamicStreams.map(s => (
              <button key={s.id} onClick={() => handleStreamSelect(s)} className="w-full text-right p-6 bg-white rounded-2xl border border-slate-200 hover:bg-blue-50 transition-all flex items-center justify-between shadow-sm">
                <span className="text-lg font-bold text-slate-700">{s.name}</span>
                <span className="text-blue-500">←</span>
              </button>
            )) : <button onClick={() => handleStreamSelect({id: 'gen', name: 'عام'})} className="w-full p-4 bg-blue-600 text-white rounded-xl">المتابعة (شعبة عامة)</button>}
          </div>
        );

      case AppStep.SUBJECT_SELECTION:
        return (
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
            {dynamicSubjects.map(subj => (
              <button key={subj.id} onClick={() => handleSubjectSelect(subj)} className="p-6 bg-white rounded-2xl border border-slate-200 hover:border-blue-500 transition-all flex items-center gap-4 text-right">
                <span className="text-3xl bg-slate-50 p-3 rounded-xl">{subj.icon}</span>
                <span className="font-bold text-slate-700 text-lg">{subj.name}</span>
              </button>
            ))}
          </div>
        );

      case AppStep.ACTION_CHOICE:
        return (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 max-w-2xl mx-auto">
            <button onClick={() => handleActionSelect('lessons')} className="p-10 bg-white rounded-3xl border-2 border-slate-100 hover:border-blue-500 hover:shadow-2xl transition-all flex flex-col items-center gap-4 group">
              <div className="w-20 h-20 bg-blue-100 rounded-2xl flex items-center justify-center text-4xl group-hover:rotate-12 transition-transform">📖</div>
              <h3 className="text-2xl font-bold text-slate-800">الدروس والشروحات</h3>
              <p className="text-slate-500 text-center">شروحات مبسطة وملخصات رسمية</p>
            </button>
            <button onClick={() => handleActionSelect('exams')} className="p-10 bg-white rounded-3xl border-2 border-slate-100 hover:border-blue-500 hover:shadow-2xl transition-all flex flex-col items-center gap-4 group">
              <div className="w-20 h-20 bg-orange-100 rounded-2xl flex items-center justify-center text-4xl group-hover:rotate-12 transition-transform">📝</div>
              <h3 className="text-2xl font-bold text-slate-800">الامتحانات الرسمية</h3>
              <p className="text-slate-500 text-center">نماذج امتحانات وزارية حقيقية</p>
            </button>
          </div>
        );

      case AppStep.LESSON_LIST:
        return (
          <div className="space-y-3">
            {lessonList.map((lesson, idx) => (
              <button key={idx} onClick={() => handleLessonSelect(lesson)} className="w-full text-right p-5 bg-white rounded-xl border border-slate-200 hover:bg-slate-50 transition-all flex items-center gap-4">
                <span className="bg-blue-500 text-white w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm">{idx + 1}</span>
                <span className="font-semibold text-slate-700">{lesson}</span>
              </button>
            ))}
          </div>
        );

      case AppStep.LESSON_VIEW:
        return currentLesson && (
          <div className="bg-white rounded-3xl shadow-xl overflow-hidden border border-slate-200">
            <div className="gradient-bg p-8 text-white">
              <h3 className="text-3xl font-bold mb-3">{currentLesson.title}</h3>
              <p className="text-white/80 leading-relaxed text-lg">{currentLesson.summary}</p>
            </div>
            <div className="p-8 prose prose-slate max-w-none">
              <div className="bg-amber-50 p-6 rounded-2xl border-l-4 border-amber-400 mb-8 italic text-slate-700 leading-8">
                {currentLesson.content.split('\n').map((line, i) => <p key={i} className="mb-4">{line}</p>)}
              </div>
              <div className="mt-12 pt-8 border-t border-slate-100">
                <h4 className="font-bold text-slate-800 mb-4">🔗 المصادر الموثوقة:</h4>
                <ul className="space-y-3">
                  {currentLesson.sources.map((src, i) => (
                    <li key={i}><a href={src} target="_blank" rel="noopener noreferrer" className="text-blue-600 hover:underline flex items-center gap-2 overflow-hidden text-ellipsis whitespace-nowrap"><span className="text-xs">🌐</span> {src}</a></li>
                  ))}
                </ul>
              </div>
            </div>
            <div className="bg-slate-50 p-6 flex justify-between items-center">
               <button onClick={goBack} className="text-slate-600 font-bold">إغلاق</button>
               <button onClick={() => window.print()} className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold">تحميل PDF</button>
            </div>
          </div>
        );

      case AppStep.EXAM_LIST:
        if (examStep === 'period') {
          return (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-w-2xl mx-auto">
              {['الفصل الأول', 'الفصل الثاني', 'الفصل الثالث', 'السنة كاملة'].map(t => (
                <button key={t} onClick={() => handlePeriodSelect(t)} className="p-8 bg-white rounded-2xl border-2 border-slate-100 hover:border-orange-500 transition-all text-center text-xl font-bold text-slate-700 shadow-sm">
                  {t}
                </button>
              ))}
            </div>
          );
        }

        if (examStep === 'quantity') {
          return (
            <div className="grid grid-cols-2 sm:grid-cols-5 gap-4">
              {Array.from({length: 10}, (_, i) => i + 1).map(num => (
                <button key={num} onClick={() => handleQuantitySelect(num)} className="p-6 bg-white rounded-xl border-2 border-slate-100 hover:border-blue-500 transition-all text-center group">
                  <span className="block text-2xl font-bold text-blue-600 mb-1">{num}</span>
                  <span className="text-xs text-slate-500">{num === 1 ? 'امتحان واحد' : num === 2 ? 'امتحانان' : `${num} امتحانات`}</span>
                </button>
              ))}
            </div>
          );
        }

        return (
          <div className="space-y-6">
            {exams.length > 0 ? (
              <div className="grid grid-cols-1 gap-4">
                {exams.map((exam, idx) => (
                  <div key={idx} className="bg-white p-6 rounded-2xl border border-slate-200 flex items-center justify-between shadow-sm hover:shadow-md transition-shadow">
                    <div className="flex flex-col gap-1">
                      <h4 className="font-bold text-lg text-slate-800">{exam.title}</h4>
                      <div className="flex gap-4 text-sm text-slate-500">
                        <span>سنة: {exam.year}</span>
                        <span>دورة: {exam.term}</span>
                      </div>
                    </div>
                    <a href={exam.url} target="_blank" rel="noopener noreferrer" className="bg-orange-500 hover:bg-orange-600 text-white px-6 py-2 rounded-xl font-bold transition-colors">تحميل الامتحان (PDF)</a>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center py-20 bg-white rounded-3xl border-2 border-dashed border-slate-200">
                <span className="text-5xl mb-4 block">📂</span>
                <p className="text-slate-500 font-bold">الامتحانات الرسمية لهذه الفترة غير متوفرة حالياً.</p>
                <button onClick={() => setExamStep('period')} className="mt-4 text-blue-600 underline">اختر فترة أخرى</button>
              </div>
            )}
          </div>
        );

      default:
        return null;
    }
  };

  const getStepTitle = () => {
    switch (state.currentStep) {
      case AppStep.COUNTRY_SELECTION: return "اختر بلدك لتخصيص المحتوى";
      case AppStep.GRADE_SELECTION: return `أهلاً بك في ${state.country?.name}، اختر النظام المعتمد`;
      case AppStep.STREAM_SELECTION: return `اختر شُعبتك الرسمية`;
      case AppStep.SUBJECT_SELECTION: return "المواد الدراسية الرسمية";
      case AppStep.ACTION_CHOICE: return `${state.subject?.name} - الخيارات المتاحة`;
      case AppStep.LESSON_LIST: return "قائمة الدروس المعتمدة";
      case AppStep.LESSON_VIEW: return "شرح الدرس الرسمي";
      case AppStep.EXAM_LIST: 
        if (examStep === 'period') return "اختر الفترة الزمنية للامتحان";
        if (examStep === 'quantity') return "كم عدد النماذج المطلوبة؟";
        return "الامتحانات الوزارية المستخرجة";
      default: return "";
    }
  };

  return (
    <Layout step={state.currentStep} onBack={goBack} title={getStepTitle()}>
      <div className="animate-in fade-in duration-700">
        {renderStep()}
      </div>
    </Layout>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { Country, Grade, Stream, Subject, Lesson, Exam } from "../types";

// Initialize the API client
const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

/**
 * Utility to retry failed API calls with exponential backoff.
 * This helps mitigate transient 500/Rpc errors.
 */
const withRetry = async <T>(fn: () => Promise<T>, retries = 3, delay = 1500): Promise<T> => {
  try {
    return await fn();
  } catch (error: any) {
    const isTransient = error?.message?.includes('500') || error?.message?.includes('Rpc failed') || error?.message?.includes('ProxyUnaryCall');
    if (isTransient && retries > 0) {
      console.warn(`API call failed (transient). Retrying in ${delay}ms...`, error);
      await new Promise(resolve => setTimeout(resolve, delay));
      return withRetry(fn, retries - 1, delay * 2);
    }
    throw error;
  }
};

/**
 * Fetches official grade levels/years for a specific country using Search Grounding.
 */
export const fetchGrades = async (country: Country): Promise<Grade[]> => {
  return withRetry(async () => {
    const ai = getAI();
    const prompt = `
      Based only on the official Ministry of Education website (${country.ministryUrl}) and official curriculum documents for ${country.name}, 
      list the official secondary education grade levels/years (e.g., 1st Secondary, 2nd Secondary, Grade 10, etc.).
      Use the EXACT official Arabic terminology used in ${country.name}.
      Return a list of grade objects with id and official name.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              name: { type: Type.STRING }
            },
            required: ["id", "name"]
          }
        }
      }
    });

    const text = response.text;
    return text ? JSON.parse(text.trim()) : [];
  });
};

