          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              name: { type: Type.STRING }
            },
            required: ["id", "name"]
          }
        }
      }
    });

    const text = response.text;
    return text ? JSON.parse(text.trim()) : [];
  });
};

