import { GoogleGenAI, Type } from "@google/genai";
import { Country, Grade, Stream, Subject, Lesson, Exam, AssessmentType } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const withRetry = async <T>(fn: () => Promise<T>, retries = 3, delay = 1500): Promise<T> => {
  try {
    return await fn();
  } catch (error: any) {
    const isTransient = error?.message?.includes('500') || error?.message?.includes('Rpc failed');
    if (isTransient && retries > 0) {
      await new Promise(resolve => setTimeout(resolve, delay));
      return withRetry(fn, retries - 1, delay * 2);
    }
    throw error;
  }
};

export const fetchGrades = async (country: Country): Promise<Grade[]> => {
  return withRetry(async () => {
    const ai = getAI();
    const prompt = `Based only on ${country.ministryUrl} for ${country.name}, list official secondary education grades (Arabic names only).`;
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: { id: { type: Type.STRING }, name: { type: Type.STRING } },
            required: ["id", "name"]
          }
        }
      }
    });
    return response.text ? JSON.parse(response.text.trim()) : [];
  });
};

