import React, { useState } from 'react';
import { 
  AppStep, 
  AppState, 
  Country, 
  Grade, 
  Stream, 
  Subject, 
  Lesson, 
  Exam,
  AssessmentType,
  AssessmentNumber
} from './types';
import { COUNTRIES } from './constants';
import Layout from './components/Layout';
import * as gemini from './services/geminiService';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    currentStep: AppStep.COUNTRY_SELECTION
  });
  const [loading, setLoading] = useState(false);
  const [dynamicGrades, setDynamicGrades] = useState<Grade[]>([]);
  const [dynamicStreams, setDynamicStreams] = useState<Stream[]>([]);
  const [dynamicSubjects, setDynamicSubjects] = useState<Subject[]>([]);
  const [dynamicAssessments, setDynamicAssessments] = useState<AssessmentType[]>([]);
  const [dynamicNumbers, setDynamicNumbers] = useState<AssessmentNumber[]>([]);
  const [lessons, setLessons] = useState<Lesson[]>([]);
  const [exams, setExams] = useState<Exam[]>([]);

  const handleCountrySelect = async (country: Country) => {
    setLoading(true);
    setState(prev => ({ ...prev, country }));
    try {
      const grades = await gemini.fetchGrades(country);
      setDynamicGrades(grades);
      setState(prev => ({ ...prev, currentStep: AppStep.GRADE_SELECTION }));
    } finally {
      setLoading(false);
    }
  };

  const handleGradeSelect = async (grade: Grade) => {
    setLoading(true);
    setState(prev => ({ ...prev, grade }));
    try {
      const streams = await gemini.fetchStreams(state.country!, grade);
      setDynamicStreams(streams);
      setState(prev => ({ ...prev, currentStep: AppStep.STREAM_SELECTION }));
    } finally {
      setLoading(false);
    }
  };

  const handleStreamSelect = async (stream: Stream) => {
    setLoading(true);
    setState(prev => ({ ...prev, stream }));
    try {
      const subjects = await gemini.fetchSubjects(state.country!, state.grade!, stream);
      setDynamicSubjects(subjects);
      setState(prev => ({ ...prev, currentStep: AppStep.SUBJECT_SELECTION }));
    } finally {
      setLoading(false);
    }
  };

  const handleSubjectSelect = (subject: Subject) => {
    setState(prev => ({ ...prev, subject, currentStep: AppStep.ACTION_CHOICE }));
  };

  const handleActionSelect = async (mode: 'lessons' | 'exams') => {
    setState(prev => ({ ...prev, mode }));
    setLoading(true);
    try {
      if (mode === 'lessons') {
        const list = await gemini.fetchLessonList(state.country!, state.grade!, state.stream!, state.subject!);
        setLessons(list);
        setState(prev => ({ ...prev, currentStep: AppStep.LESSON_LIST }));
      } else {
        const assessments = await gemini.fetchAssessmentTypes(state.country!, state.grade!, state.stream!, state.subject!);
        setDynamicAssessments(assessments);
        setState(prev => ({ ...prev, currentStep: AppStep.ASSESSMENT_TYPE_SELECTION }));
      }
    } finally {
      setLoading(false);
    }
  };

  const handleAssessmentTypeSelect = async (type: AssessmentType) => {
    setLoading(true);
    setState(prev => ({ ...prev, assessmentType: type }));
    try {
      const numbers = await gemini.fetchAssessmentNumbers(state.country!, state.grade!, state.stream!, state.subject!, type);
      setDynamicNumbers(numbers);
      setState(prev => ({ ...prev, currentStep: AppStep.ASSESSMENT_NUMBER_SELECTION }));
    } finally {
      setLoading(false);
    }
  };

  const handleAssessmentNumberSelect = async (num: AssessmentNumber) => {
    setLoading(true);
    setState(prev => ({ ...prev, assessmentNumber: num }));
    try {
      const results = await gemini.fetchExamsByFullCriteria(
        state.country!, 
        state.grade!, 
        state.stream!, 
        state.subject!, 
        state.assessmentType!, 
        num
      );
      setExams(results);
      setState(prev => ({ ...prev, currentStep: AppStep.EXAM_LIST }));
    } finally {
      setLoading(false);
    }
  };

  const openPdf = (url: string) => {
    setState(prev => ({ ...prev, currentPdfUrl: url, currentStep: AppStep.PDF_VIEW }));
  };

  const goBack = () => {
    const prevStepMap: Record<AppStep, AppStep> = {
      [AppStep.COUNTRY_SELECTION]: AppStep.COUNTRY_SELECTION,
      [AppStep.GRADE_SELECTION]: AppStep.COUNTRY_SELECTION,
      [AppStep.STREAM_SELECTION]: AppStep.GRADE_SELECTION,
      [AppStep.SUBJECT_SELECTION]: AppStep.STREAM_SELECTION,
      [AppStep.ACTION_CHOICE]: AppStep.SUBJECT_SELECTION,
      [AppStep.LESSON_LIST]: AppStep.ACTION_CHOICE,
      [AppStep.ASSESSMENT_TYPE_SELECTION]: AppStep.ACTION_CHOICE,
      [AppStep.ASSESSMENT_NUMBER_SELECTION]: AppStep.ASSESSMENT_TYPE_SELECTION,
      [AppStep.EXAM_LIST]: AppStep.ASSESSMENT_NUMBER_SELECTION,
      [AppStep.PDF_VIEW]: state.mode === 'lessons' ? AppStep.LESSON_LIST : AppStep.EXAM_LIST,
    };
    setState(prev => ({ ...prev, currentStep: prevStepMap[prev.currentStep] }));
  };

  const renderStep = () => {
    if (loading) {
      return (
        <div className="flex flex-col items-center justify-center py-20 space-y-6">
          <div className="w-16 h-16 border-4 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
          <p className="text-xl font-medium text-slate-600 animate-pulse text-center">جاري الوصول للمصادر الرسمية المعتمدة...</p>
        </div>
      );
    }

    switch (state.currentStep) {
      case AppStep.COUNTRY_SELECTION:
        return (
          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
            {COUNTRIES.map(c => (
              <button key={c.id} onClick={() => handleCountrySelect(c)} className="glass p-6 rounded-2xl border border-slate-200 hover:border-blue-500 hover:scale-105 transition-all flex flex-col items-center gap-3">
                <span className="text-4xl">{c.flag}</span>
                <span className="font-bold text-slate-700">{c.name}</span>
              </button>
            ))}
          </div>
        );

      case AppStep.GRADE_SELECTION:
        return (
          <div className="space-y-4 max-w-lg mx-auto">
            {dynamicGrades.map(g => (
              <button key={g.id} onClick={() => handleGradeSelect(g)} className="w-full text-right p-6 bg-white rounded-2xl border border-slate-200 hover:bg-blue-50 transition-all flex items-center justify-between shadow-sm">
                <span className="text-lg font-bold text-slate-700">{g.name}</span>
                <span className="text-blue-500">←</span>
              </button>
            ))}
          </div>
        );

      case AppStep.STREAM_SELECTION:
        return (
          <div className="space-y-4 max-w-lg mx-auto">
            {dynamicStreams.length > 0 ? dynamicStreams.map(s => (
              <button key={s.id} onClick={() => handleStreamSelect(s)} className="w-full text-right p-6 bg-white rounded-2xl border border-slate-200 hover:bg-blue-50 transition-all flex items-center justify-between shadow-sm">
                <span className="text-lg font-bold text-slate-700">{s.name}</span>
                <span className="text-blue-500">←</span>
              </button>
            )) : <button onClick={() => handleStreamSelect({id: 'gen', name: 'عام'})} className="w-full p-4 bg-blue-600 text-white rounded-xl">المتابعة (شعبة عامة)</button>}
          </div>
        );

      case AppStep.SUBJECT_SELECTION:
        return (
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
            {dynamicSubjects.map(subj => (
              <button key={subj.id} onClick={() => handleSubjectSelect(subj)} className="p-6 bg-white rounded-2xl border border-slate-200 hover:border-blue-500 transition-all flex items-center gap-4 text-right">
                <span className="text-3xl bg-slate-50 p-3 rounded-xl">{subj.icon}</span>
                <span className="font-bold text-slate-700 text-lg">{subj.name}</span>
              </button>
            ))}
          </div>
        );

      case AppStep.ACTION_CHOICE:
        return (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 max-w-2xl mx-auto">
            <button onClick={() => handleActionSelect('lessons')} className="p-10 bg-white rounded-3xl border-2 border-slate-100 hover:border-blue-500 hover:shadow-2xl transition-all flex flex-col items-center gap-4">
              <div className="w-20 h-20 bg-blue-100 rounded-2xl flex items-center justify-center text-4xl">📖</div>
              <h3 className="text-2xl font-bold text-slate-800">الدروس الرسمية</h3>
              <p className="text-slate-500 text-center">فتح الكتاب المدرسي مباشرة</p>
            </button>
            <button onClick={() => handleActionSelect('exams')} className="p-10 bg-white rounded-3xl border-2 border-slate-100 hover:border-blue-500 hover:shadow-2xl transition-all flex flex-col items-center gap-4">
              <div className="w-20 h-20 bg-orange-100 rounded-2xl flex items-center justify-center text-4xl">📝</div>
              <h3 className="text-2xl font-bold text-slate-800">الفروض والامتحانات</h3>
              <p className="text-slate-500 text-center">نماذج رسمية من سنوات سابقة</p>
            </button>
          </div>
        );

      case AppStep.LESSON_LIST:
        return (
          <div className="space-y-3">
            {lessons.map((lesson, idx) => (
              <button key={idx} onClick={() => openPdf(lesson.pdfUrl)} className="w-full text-right p-5 bg-white rounded-xl border border-slate-200 hover:bg-slate-50 transition-all flex items-center gap-4">
                <span className="bg-blue-500 text-white w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm shrink-0">{idx + 1}</span>
                <span className="font-semibold text-slate-700 flex-1">{lesson.title}</span>
                <span className="text-blue-400">📄 فتح الكتاب</span>
              </button>
            ))}
          </div>
        );

      case AppStep.ASSESSMENT_TYPE_SELECTION:
        return (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-w-2xl mx-auto">
            {dynamicAssessments.map(type => (
              <button key={type.id} onClick={() => handleAssessmentTypeSelect(type)} className="p-8 bg-white rounded-2xl border-2 border-slate-100 hover:border-orange-500 transition-all text-center text-xl font-bold text-slate-700">
                {type.name}
              </button>
            ))}
          </div>
        );

      case AppStep.ASSESSMENT_NUMBER_SELECTION:
        return (
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 max-w-2xl mx-auto">
            {dynamicNumbers.map(num => (
              <button key={num.id} onClick={() => handleAssessmentNumberSelect(num)} className="p-6 bg-white rounded-2xl border-2 border-slate-100 hover:border-blue-500 transition-all text-center text-lg font-bold text-slate-700">
                {num.name}
              </button>
            ))}
          </div>
        );

      case AppStep.EXAM_LIST:
        return (
          <div className="space-y-4">
            {exams.length > 0 ? exams.map((exam, idx) => (
              <button key={idx} onClick={() => openPdf(exam.pdfUrl)} className="w-full bg-white p-6 rounded-2xl border border-slate-200 flex items-center justify-between shadow-sm hover:shadow-md transition-shadow">
                <div className="text-right">
                  <h4 className="font-bold text-lg text-slate-800">{exam.title}</h4>
                  <span className="text-sm text-slate-500">سنة: {exam.year}</span>
                </div>
                <div className="bg-orange-500 text-white px-6 py-2 rounded-xl font-bold">📄 عرض PDF</div>
              </button>
            )) : (
              <div className="text-center py-20 bg-white rounded-3xl border-2 border-dashed border-slate-200">
                <p className="text-slate-500 font-bold">لم تتوفر نسخ رقمية رسمية لهذا الفرض حالياً.</p>
              </div>
            )}
          </div>
        );

      case AppStep.PDF_VIEW:
        return (
          <div className="w-full h-[75vh] rounded-3xl overflow-hidden border border-slate-200 shadow-2xl bg-white relative">
            <iframe src={state.currentPdfUrl} className="w-full h-full" title="PDF Viewer" />
            <div className="absolute bottom-6 right-6 flex gap-3">
               <button onClick={goBack} className="bg-slate-800 text-white px-6 py-3 rounded-xl font-bold shadow-lg">إغلاق</button>
               <a href={state.currentPdfUrl} target="_blank" rel="noopener noreferrer" className="bg-blue-600 text-white px-6 py-3 rounded-xl font-bold shadow-lg">تحميل الملف</a>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  const getStepTitle = () => {
    switch (state.currentStep) {
      case AppStep.COUNTRY_SELECTION: return "اختر بلدك";
      case AppStep.GRADE_SELECTION: return "اختر السنة الدراسية الرسمية";
      case AppStep.STREAM_SELECTION: return "اختر الشعبة المعتمدة";
      case AppStep.SUBJECT_SELECTION: return "المواد الدراسية المقررة";
      case AppStep.ACTION_CHOICE: return state.subject?.name;
      case AppStep.LESSON_LIST: return "الكتب المدرسية والدروس";
      case AppStep.ASSESSMENT_TYPE_SELECTION: return "نوع الفرض / الامتحان";
      case AppStep.ASSESSMENT_NUMBER_SELECTION: return "رقم الفرض المعتمد";
      case AppStep.EXAM_LIST: return `نماذج: ${state.assessmentType?.name} ${state.assessmentNumber?.name}`;
      case AppStep.PDF_VIEW: return "معاينة الملف الرسمي";
      default: return "";
    }
  };

  return (
    <Layout step={state.currentStep} onBack={goBack} title={getStepTitle()}>
      <div className="animate-in fade-in duration-700">
        {renderStep()}
      </div>
    </Layout>
  );
};

export default App;

