        );

      case AppStep.ASSESSMENT_NUMBER_SELECTION:
        return (
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 max-w-2xl mx-auto">
            {dynamicNumbers.map(num => (
              <button key={num.id} onClick={() => handleAssessmentNumberSelect(num)} className="p-6 bg-white rounded-2xl border-2 border-slate-100 hover:border-blue-500 transition-all text-center text-lg font-bold text-slate-700">
                {num.name}
