      case AppStep.EXAM_LIST:
        return (
          <div className="space-y-4">
            {exams.length > 0 ? exams.map((exam, idx) => (
              <button key={idx} onClick={() => openPdf(exam.pdfUrl)} className="w-full bg-white p-6 rounded-2xl border border-slate-200 flex items-center justify-between shadow-sm hover:shadow-md transition-shadow">
