        );

      case AppStep.PDF_VIEW:
        return (
          <div className="fixed inset-0 z-[100] bg-black flex flex-col animate-in fade-in zoom-in duration-300">
            <div className="bg-slate-900 text-white p-4 flex justify-between items-center shadow-2xl">
              <span className="font-bold text-sm truncate max-w-[200px]">الملف الرسمي - فهمني</span>
              <button onClick={goBack} className="bg-red-500/20 hover:bg-red-500 text-white px-5 py-2 rounded-full text-sm font-bold transition-all border border-red-500/30">إغلاق</button>
            </div>
            <div className="flex-1 bg-slate-800 relative">
              {/* استخدام embed كبديل متوافق أكثر مع WebView الأندرويد لفتح ملفات PDF داخلياً */}
              <object 
                data={state.currentPdfUrl} 
                type="application/pdf" 
                className="w-full h-full"
              >
                <div className="flex flex-col items-center justify-center h-full text-white p-10 text-center">
                  <p className="mb-6">المعذرة، لا يمكن عرض هذا الملف مباشرة داخل التطبيق على هذا الجهاز.</p>
                  <a href={state.currentPdfUrl} target="_blank" rel="noopener noreferrer" className="bg-blue-600 text-white px-8 py-3 rounded-2xl font-bold shadow-xl">تحميل الملف وفتحه خارجياً</a>
                </div>
              </object>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  const getStepTitle = () => {
    switch (state.currentStep) {
      case AppStep.COUNTRY_SELECTION: return "اختر بلدك";
      case AppStep.GRADE_SELECTION: return "اختر السنة الدراسية";
      case AppStep.STREAM_SELECTION: return "اختر الشعبة المعتمدة";
      case AppStep.SUBJECT_SELECTION: return "المواد الدراسية";
      case AppStep.ACTION_CHOICE: return state.subject?.name;
      case AppStep.LESSON_LIST: return "الكتب المدرسية";
      case AppStep.ASSESSMENT_TYPE_SELECTION: return "نوع التقييم";
      case AppStep.ASSESSMENT_NUMBER_SELECTION: return "رقم الفرض";
      case AppStep.EXAM_LIST: return `نماذج: ${state.assessmentType?.name} ${state.assessmentNumber?.name}`;
      default: return "";
    }
  };

  return (
    <Layout step={state.currentStep} onBack={state.currentStep === AppStep.PDF_VIEW ? undefined : goBack} title={getStepTitle()}>
      <div className="animate-in fade-in duration-700">
        {renderStep()}
      </div>
    </Layout>
  );
};

