            </button>
            <button onClick={() => handleActionSelect('exams')} className="p-10 bg-white rounded-3xl border-2 border-slate-100 hover:border-orange-500 hover:shadow-2xl transition-all flex flex-col items-center gap-4">
              <div className="w-20 h-20 bg-orange-100 rounded-2xl flex items-center justify-center text-4xl">📝</div>
              <h3 className="text-2xl font-bold text-slate-800">الامتحانات والفروض</h3>
              <p className="text-slate-500 text-center">نماذج رسمية من سنوات سابقة</p>
            </button>
          </div>
        );

      case AppStep.ASSESSMENT_TYPE_SELECTION:
        return (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 max-w-2xl mx-auto">
            {dynamicAssessments.map(type => (
              <button key={type.id} onClick={() => handleAssessmentTypeSelect(type)} className="p-8 bg-white rounded-2xl border-2 border-slate-100 hover:border-blue-600 transition-all text-center text-xl font-bold text-slate-700 shadow-sm">
                {type.name}
              </button>
            ))}
          </div>
        );

      case AppStep.ASSESSMENT_NUMBER_SELECTION:
        return (
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-4 max-w-xl mx-auto">
            {dynamicNumbers.map(num => (
              <button key={num.id} onClick={() => handleAssessmentNumberSelect(num)} className="p-6 bg-white rounded-2xl border-2 border-slate-100 hover:border-orange-500 transition-all text-center text-lg font-bold text-slate-700 shadow-sm">
                {num.name}
              </button>
            ))}
          </div>
        );

      case AppStep.EXAM_LIST:
        return (
          <div className="space-y-4">
            {exams.length > 0 && exams.length < 10 && (
              <div className="bg-blue-50 border-r-4 border-blue-500 p-4 mb-4 rounded-lg">
                <p className="text-blue-800 font-bold text-sm">⚠️ متاح حالياً {exams.length} نماذج رسمية فقط لهذا التصنيف.</p>
              </div>
            )}
            {exams.length > 0 ? exams.map((exam, idx) => (
              <button key={idx} onClick={() => openPdf(exam.pdfUrl)} className="w-full bg-white p-6 rounded-2xl border border-slate-200 flex items-center justify-between shadow-sm hover:shadow-md transition-shadow active:scale-95">
                <div className="text-right">
                  <h4 className="font-bold text-lg text-slate-800">{exam.title}</h4>
                  <span className="text-sm text-slate-500">الإصدار الرسمي: {exam.year}</span>
                </div>
                <div className="bg-orange-600 text-white px-6 py-2 rounded-xl font-bold shadow-lg text-sm shrink-0">فتح PDF فوري</div>
              </button>
            )) : (
              <div className="text-center py-20 bg-white rounded-3xl border-2 border-dashed border-slate-200">
                <p className="text-slate-500 font-bold">لا توجد نسخ رقمية رسمية متاحة حالياً لهذا الفرض.</p>
              </div>
            )}
          </div>
        );

      case AppStep.LESSON_LIST:
        return (
          <div className="space-y-3">
            {lessons.map((lesson, idx) => (
              <button key={idx} onClick={() => openPdf(lesson.pdfUrl)} className="w-full text-right p-5 bg-white rounded-xl border border-slate-200 hover:bg-slate-50 transition-all flex items-center gap-4 active:scale-[0.98]">
                <span className="bg-blue-600 text-white w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm shrink-0">{idx + 1}</span>
                <span className="font-bold text-slate-700 flex-1 truncate">{lesson.title}</span>
                <span className="text-blue-500 font-bold text-xs shrink-0">📄 عرض الكتاب</span>
              </button>
            ))}
          </div>
        );

      case AppStep.PDF_VIEW:
        return (
          <div className="fixed inset-0 z-[100] bg-black flex flex-col animate-in fade-in zoom-in duration-300">
            <div className="bg-slate-900 text-white p-4 flex justify-between items-center shadow-2xl">
              <span className="font-bold text-sm truncate max-w-[250px]">{state.assessmentType?.name} {state.assessmentNumber?.name}</span>
              <button onClick={goBack} className="bg-red-600 text-white px-6 py-2 rounded-full text-sm font-bold transition-all shadow-lg active:scale-90">إغلاق</button>
            </div>
            <div className="flex-1 bg-slate-800 relative">
              <object 
                data={state.currentPdfUrl} 
                type="application/pdf" 
                className="w-full h-full"
              >
                <div className="flex flex-col items-center justify-center h-full text-white p-10 text-center">
                  <p className="mb-6 font-bold">جهازك لا يدعم عرض الـ PDF مباشرة داخل التطبيق.</p>
                  <a href={state.currentPdfUrl} target="_blank" rel="noopener noreferrer" className="bg-blue-600 text-white px-8 py-3 rounded-2xl font-bold shadow-xl">فتح في قارئ خارجي</a>
                </div>
              </object>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  const getStepTitle = () => {
    switch (state.currentStep) {
      case AppStep.COUNTRY_SELECTION: return "فهمني - اختر بلدك";
      case AppStep.GRADE_SELECTION: return "السنة الدراسية الرسمية";
      case AppStep.STREAM_SELECTION: return "الشعبة أو التخصص المعتمد";
      case AppStep.SUBJECT_SELECTION: return "المواد الدراسية المقررة";
      case AppStep.ACTION_CHOICE: return state.subject?.name;
      case AppStep.ASSESSMENT_TYPE_SELECTION: return "تصنيف التقييم الرسمي";
      case AppStep.ASSESSMENT_NUMBER_SELECTION: return "رقم التقييم المعتمد";
      case AppStep.EXAM_LIST: return `نماذج: ${state.assessmentType?.name} ${state.assessmentNumber?.name}`;
      case AppStep.LESSON_LIST: return "قائمة الدروس والكتب";
      default: return "";
    }
  };

  return (
    <Layout step={state.currentStep} onBack={state.currentStep === AppStep.PDF_VIEW ? undefined : goBack} title={getStepTitle()}>
      <div className="animate-in fade-in duration-700">
        {renderStep()}
      </div>
    </Layout>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { Country, Grade, Stream, Subject, Lesson, Exam, AssessmentType, AssessmentNumber } from "../types";

const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const withRetry = async <T>(fn: () => Promise<T>, retries = 3, delay = 1500): Promise<T> => {
  try {
    return await fn();
  } catch (error: any) {
    const isTransient = error?.message?.includes('500') || error?.message?.includes('Rpc failed');
    if (isTransient && retries > 0) {
      await new Promise(resolve => setTimeout(resolve, delay));
      return withRetry(fn, retries - 1, delay * 2);
    }
    throw error;
  }
};

export const fetchGrades = async (country: Country): Promise<Grade[]> => {
  return withRetry(async () => {
    const ai = getAI();
    const prompt = `Based only on ${country.ministryUrl} for ${country.name}, list official secondary education grades (Arabic names only). Use exact official terminology.`;
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: { id: { type: Type.STRING }, name: { type: Type.STRING } },
            required: ["id", "name"]
          }
        }
      }
    });
    return response.text ? JSON.parse(response.text.trim()) : [];
  });
};

