export const fetchExamsByFullCriteria = async (
  country: Country, 
  grade: Grade, 
  stream: Stream, 
  subject: Subject, 
  type: AssessmentType, 
  number: AssessmentNumber
): Promise<Exam[]> => {
  return withRetry(async () => {
    const ai = getAI();
    const prompt = `SEARCH REQUIREMENT: Find exactly 10 (if available) DIRECT PDF links for real past exams from ${country.name}: ${grade.name}, ${subject.name}, ${type.name} ${number.name}. 
    Rules: 
    1. Direct PDF only. 
    2. No commercial site names in titles. 
    3. Sort by most recent years.`;

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: { 
              id: { type: Type.STRING }, 
              title: { type: Type.STRING }, 
              year: { type: Type.STRING }, 
              pdfUrl: { type: Type.STRING } 
            },
            required: ["id", "title", "year", "pdfUrl"]
          }
        }
      }
    });
    const results: Exam[] = response.text ? JSON.parse(response.text.trim()) : [];
    return results.slice(0, 10);
  });
};
